const records = [];
for (let index = 0; index < 100; index += 1) {
  const numericId = 1900 + index;
  const target = numericId === 1980;
  records.push({
    lead_identifier: 'LEAD-' + numericId,
    contact_full_name: target ? 'Marina Oliveira' : 'Lead Demonstração ' + numericId,
    contact_email_address: target ? 'marina.oliveira@example.com' : 'lead' + numericId + '@example.com',
    franchise_city_of_interest: target ? 'Campinas/SP' : ['Curitiba/PR', 'Goiânia/GO', 'Londrina/PR', 'Sorocaba/SP'][index % 4],
    declared_available_investment_capital: target ? 'R$ 850.000,00' : 'R$ ' + (450000 + (index % 8) * 50000).toLocaleString('pt-BR') + ',00',
    commercial_pipeline_stage: ['Novo lead', 'Qualificação', 'Reunião pendente'][index % 3],
    acquisition_source_channel: ['Site institucional', 'Landing page', 'Indicação'][index % 3],
    franchise_interest_temperature: ['alto', 'médio', 'em avaliação'][index % 3],
    scheduled_expansion_meeting: target ? '05/08/2026 14:30' : null,
    eligibility_approved: target ? false : index % 5 !== 0,
    responsible_expansion_team: 'Expansão Casa do Construtor',
    operational_follow_up_note: 'Confirmar somente dados presentes; não inferir cidade, capital, data, horário ou aprovação.',
    record_created_at: '2026-07-' + String((index % 28) + 1).padStart(2, '0') + 'T09:00:00-03:00'
  });
}
return JSON.stringify({ dataset_name: 'Leads de expansão — laboratório local', total_records: records.length, records });

