const comparison = $input.first().json;
const savings = comparison.tokenSavings || {};
const telemetry = comparison.modelTelemetry || {};
const optimization = telemetry.optimized?.optimization || {};
const baseline = String($('Resultado Baseline').first().json.baseline_output || '');
const optimized = String($('Resultado Maximum Savings').first().json.optimized_output || '');
const expected = ["LEAD-1980","Campinas/SP","R$ 850.000,00","05/08/2026 14:30","false"];
const normalize = (value) => String(value || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
const factsPreserved = expected.every((fact) => normalize(baseline).includes(normalize(fact)) && normalize(optimized).includes(normalize(fact)));
return [{ json: {
  output: [
    '## Maximum Savings — prova real',
    '**Provider:** ' + savings.before + ' → ' + savings.after + ' tokens (' + savings.percent + '%)',
    '**Conteúdo elegível:** ' + optimization.eligibleTokensBefore + ' → ' + optimization.eligibleTokensAfter + ' tokens (' + optimization.eligibleSavingsPercent + '%)',
    '**Recuperação exata exigida:** ' + String(optimization.retrievalRequired),
    '**Meta 70–90% atingida:** ' + String(optimization.targetBandReached),
    '**5/5 fatos preservados:** ' + String(factsPreserved)
  ].join('\n'),
  baselineOutput: baseline,
  optimizedOutput: optimized,
  providerSavings: savings,
  eligibleSavings: {
    before: optimization.eligibleTokensBefore,
    after: optimization.eligibleTokensAfter,
    percent: optimization.eligibleSavingsPercent,
    targetBandReached: optimization.targetBandReached,
    retrievalRequired: optimization.retrievalRequired,
    resources: optimization.virtualizedResourceIds,
    fallbackReason: optimization.targetNotReachedReason || null,
    storageFallbackUsed: optimization.storageFallbackUsed
  },
  factsPreserved,
  outputsMatch: baseline === optimized,
  datasetRecords: 100,
  targetIndex: 80,
  model: 'models/gemini-2.5-flash',
  measurement: 'provider'
} }];
